def emit(nodes: dict, edges: list, res: dict, tx: int = 1) -> str:
    L = []
    L.append(";; hoshimori 星守 — GENERATED kotoba Datom log (ADR-2606073600). DO NOT hand-edit.")
    L.append(";; Canonical EAVT state (ADR-2605312345). [e a v tx op].")
    L.append(";; GROUND op :add = durable. DERIVED :bond/is-transient = computed on read (N1/G2).")
    L.append(";; G1: shell/regime-aggregate only — NO precise predictive ephemeris.")
    L.append("[")

    for nid in nodes:
        n = nodes[nid]
        for a in NODE_ATTRS:
            if a in n and n[a] is not None:
                L.append(f"[{_fmt(nid)} {a} {_fmt(n[a])} {tx} :add]")

    for e in edges:
        eid = f"en.{e[':en/from']}.{e[':en/kind'].lstrip(':')}.{e[':en/to']}"
        for a in EDGE_ATTRS:
            if a in e and e[a] is not None:
                L.append(f"{'[' + _fmt(eid)} {a} {_fmt(e[a])} {tx} :add]")

    L.append(";; ── DERIVED readouts (transient; integral of incident 縁, computed on read) ──")
    for nid, v in sorted(res["congestion"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/congestion-concentration {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["stewardship"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/stewardship-buffer {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["fragility"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/dependency-fragility {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["congestion_out"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/congestion-imposed {v:g} {tx} :derived] ;; :bond/is-transient true")

    L.append("]")
    return "\n".join(L) + "\n"
```

